    if (highContrastEnabled) {
        // Habilita o contraste: Adiciona a classe
        link.classList.add(highContrastClass);
    } else {
        // Desabilita o contraste: Remove a classe
        link.classList.remove(highContrastClass);
    }
}


	// Seletor para o container de acessibilidade
