var idArrowPrincipais = document.getElementById('idArrowPrincipais');
var linkPrincipaisSistemas = document.querySelector('.tesouroHeaderlink'); 

if (idArrowPrincipais && linkPrincipaisSistemas) {
    if (highContrastEnabled) {
        // Contraste Ativado:

        // 1. Fundo do link (pai) para branco (sobrescreve o default)
        linkPrincipaisSistemas.style.backgroundColor = "white"; 

        // 2. Cor do TEXTO do link (pai) para PRETO (sobrescreve a herança da classe)
        linkPrincipaisSistemas.style.color = "black";

        // 3. Estilo da Seta (i): Fundo transparente e cor preta
        idArrowPrincipais.style.backgroundColor = "transparent";
        idArrowPrincipais.style.color = "black";

    } else {
        // Contraste Desativado: Limpa todos os estilos inline
        linkPrincipaisSistemas.style.backgroundColor = "";
        linkPrincipaisSistemas.style.color = "";
        idArrowPrincipais.style.backgroundColor = "";
        idArrowPrincipais.style.color = "";
    }
}



