		var svgs = document.querySelectorAll('svg.bi.bi-circle-half');
		for (var i9 = 0; i9 < svgs.length; i9++) {
				var svg = svgs[i9];
				if (highContrastEnabled) {
						// fundo branco
						svg.style.backgroundColor = "#FFFFFF";
						svg.style.borderRadius = "50%"; // deixar circular o fundo branco

						// desenha metade preta, metade branca
						// (supondo SVG já com paths, muda o fill da metade preta)
						var paths = svg.querySelectorAll('path');
						for (var j6 = 0; j6 < paths.length; j6++) {
								paths[j6].style.fill = "#000000"; // preto na metade
						}
				} else {
						svg.style.backgroundColor = "";
						var paths2 = svg.querySelectorAll('path');
						for (var j7 = 0; j7 < paths2.length; j7++) {
								paths2[j7].style.fill = ""; // resetar cor
						}
				}
		}



			var searchWrapperElements = document.getElementsByClassName('search-wrapper');
		for (var z1 = 0; z1 < searchWrapperElements.length; z1++) {
			searchWrapperElements[z1].style.backgroundColor = highContrastEnabled ? "transparent" : "";
		}

			// Para .fa.fa-search
		var searchIcons = document.getElementsByClassName('fa fa-search');
		for (var z2 = 0; z2 < searchIcons.length; z2++) {
			if (highContrastEnabled) {
				searchIcons[z2].style.color = "#000"; // cor preta
				 searchIcons[z2].style.backgroundColor = highContrastEnabled ? "#FFFFFF" : "";
				// searchIcons[z2].style.backgroundColor = "#FFF";
			} else {
				searchIcons[z2].style.color = "";
				searchIcons[z2].style.backgroundColor = "";
			}
		}
		// Para .btn.search-button
		var searchButtons = document.querySelectorAll('.btn.search-button');
		for (var z3 = 0; z3 < searchButtons.length; z3++) {
			searchButtons[z3].style.backgroundColor = highContrastEnabled ? "#FFFFFF" : "";
			searchButtons[z3].style.color = highContrastEnabled ? "#000000" : "";
		}

	// Navbar
var navbar = document.querySelector('.navbar');
if (navbar) {
  if (highContrastEnabled) {
    navbar.style.borderBottom = "1.2rem solid #D3D3D3"; // CINZA claro
  } else {
    navbar.style.borderBottom = ""; // reseta se sair do modo contraste
  }
}


		// linha-topo




	// lado-esquerdo
	var ladoEsquerdoElements = document.getElementsByClassName('lado-esquerdo');
	for (var z5 = 0; z5 < ladoEsquerdoElements.length; z5++) {
		ladoEsquerdoElements[z5].style.backgroundColor = highContrastEnabled ? "transparent" : "";

	}

	// lado-direito
	var ladoDireitoElements = document.getElementsByClassName('lado-direito');
	for (var z6 = 0; z6 < ladoDireitoElements.length; z6++) {
		ladoDireitoElements[z6].style.backgroundColor = highContrastEnabled ? "transparent" : "";

}
		var badge = document.getElementByClassName('logo');
			if(highContrastEnabled){
				badge.style.backgroundColor = highContrastEnabled ? "transparent" : "";
			}



}
	/*var infoSelect = document.getElementsByTagName('option');
	for (var d5 = 0; d5 < infoSelect.length; d5++) {
		infoSelect[d5].style.backgroundColor = highContrastEnabled ? "white" : "";
		infoSelect[d5].style.color = highContrastEnabled ? "black" : "";
	}*/

});

};




