@media (max-width: 768px) {
    /* 1. **CRUCIAL:** Força o container principal a empilhar seus filhos (lista de links e container de busca) */
    .header-menu {
        display: flex !important; /* Mantém o display: flex */
        flex-direction: column !important; /* Força a coluna: busca abaixo da lista */
        align-items: center !important; /* Centraliza a coluna se quiser */
        width: 100%;
        min-height: auto; /* Permite que a altura se ajuste ao conteúdo */
        overflow-x: hidden; /* Evita a barra de rolagem horizontal */
    }

    /* 2. Garante que a lista de menu ocupe a largura total para mobile */
    .header-menu .menu-list {
        display: block !important; /* Ou use flex-direction: column */
        width: 100% !important;
        /* Mantenha seu padding: 0; margin: 0; */
    }

    /* 3. Garante que o container da busca ocupe a largura total */
    .header-container {
        width: 100% !important;
        padding: 0;
        margin-top: 5px; /* Adiciona um espaço para separar da lista de links */
    }

    /* 4. Garante que o .row empilhe ou se comporte como bloco */
    .header-container .row {
        flex-direction: column !important; /* Mantém a regra de empilhamento interna */
        display: block !important; /* Garante que o row não force layout horizontal */
        width: 100% !important;
        padding: 0 15px !important;
    }

    /* 5. Garante que o search-wrapper seja exibido e ocupe o espaço */
    .search-wrapper {
        display: block !important;
        width: 100% !important;
        padding-right: 0 !important; /* Remove o padding-right que pode estar puxando */
        /* Remova ou zere o display: none */
    }
  #tesouroPointer {
  padding-left: 1.5rem;
  }
}
