}
/* --- Responsividade do Widget de Busca --- */

/* 1. Para telas grandes (ex: 993px - 1200px) */
/* Mantém o padrão, mas reduz um pouco se 400px for muito. */
@media (min-width: 993px) and (max-width: 1200px) {
    .search-widget {
        max-width: 350px; /* Reduz a largura máxima do widget */
    }
}

/* 2. Para tablets (ex: 769px - 992px) */
@media (min-width: 769px) and (max-width: 992px) {
    .search-widget {
        max-width: 300px; /* Reduz mais a largura */
    }
}

/* 3. Para tablets/celulares grandes (ex: 541px - 768px) */
/* Nesta faixa, é comum deixar a busca com uma largura maior ou total, mas com um padding. */
@media (min-width: 541px) and (max-width: 768px) {
    .search-widget {
        max-width: 90%; /* Ocupa 90% da largura do container pai */
    }
    .search-wrapper {
        justify-content: center; /* Centraliza a caixa de busca */
    }
}

/* 4. Para celulares (ex: max-width: 540px) */
/* Aqui, a busca geralmente ocupa a largura total para facilitar o uso. */
@media (max-width: 540px) {
    .search-widget {
        max-width: 100%; /* Ocupa 100% da largura, dentro do padding do container */
    }
    /* O padding deve ser aplicado no .search-wrapper para dar margem nas laterais */
    .search-wrapper {
        padding: 10px 15px !important; 
        box-sizing: border-box;
    }
}

